199:   cambiarPagina(event: PageEvent) {
200:     this.paginaActual = event.pageIndex;
201:     this.tamanioPagina = event.pageSize;
202:     this.consultar(false);
203:   }
204: 
205:   consultar(resetPage: boolean = true) {
206:     if (resetPage) {
207:       if (this.paginator) {
208:         this.paginator.firstPage();
209:       }
210:       this.paginaActual = 0;
211:     }
212: 
213:     this.isLoading = true;
214:     const params = {
215:       ...this.prepararParametros(),
216:       limit: this.tamanioPagina,
217:       offset: this.paginaActual * this.tamanioPagina,
218:     };
219: 
220:     this.contratoMidService.getContratos(params).subscribe({
221:       next: (response) => {
222:         if (response.Success && response.Status === 200) {
223:           this.dataSource.data = response.Data;
224:           this.totalRegistros = response.Metadata.total;
225:         }
226:       },
227:       error: async (error) => {
228:         await this.alertService.showErrorAlert('Error al consultar contratos');
229:       },
230:       complete: () => {
231:         this.isLoading = false;
232:       },
233:     });
234:   }
235: 
236:   limpiarFiltros() {
237:     this.form.reset();
238:     this.paginaActual = 0;
239:     if (this.paginator) {
240:       this.paginator.firstPage();
241:     }
242:     this.consultar();
243:   }
244: 
245:   verDetalle(contrato: ContratoGeneral) {
246:     this.router.navigate(['/detalle', contrato.id]);
247:   }
