249:   private prepararParametros() {
250:     const formValues = this.form.value;
251:     const params: any = {
252:       limit: this.tamanioPagina,
253:       offset: this.paginaActual * this.tamanioPagina,
254:     };
255: 
256:     if (formValues.unidadEjecutora)
257:       params.unidad_ejecutora_id = formValues.unidadEjecutora;
258:     if (formValues.vigencia) params.vigencia = formValues.vigencia;
259:     if (formValues.tipoContratoId)
260:       params.tipoContratoId = formValues.tipoContratoId;
261:     if (formValues.tipoPersona) {
262:       params.contratista = params.contratista || {};
263:       params.contratista.tipo_persona_id = formValues.tipoPersona;
264:     }
265:     if (formValues.contratista) {
266:       params.contratista = params.contratista || {};
267:       params.contratista.numero_documento = formValues.contratista;
268:     }
269:     if (formValues.numeroElaboracion)
270:       params.numeroElaboracion = formValues.numeroElaboracion;
271:     if (formValues.numeroContrato) params.id = formValues.numeroContrato;
272:     if (formValues.estado) {
273:       params.estados = params.estados || {};
274:       params.estados.estado_parametro_id = formValues.estado;
275:     }
276:     if (formValues.fechaDesde || formValues.fechaHasta) {
277:       params.fechaCreacion = {};
278: 
279:       if (formValues.fechaDesde) {
280:         params.fechaCreacion.start = new Date(formValues.fechaDesde)
281:           .toISOString()
282:           .split('T')[0];
283:       }
284: 
285:       if (formValues.fechaHasta) {
286:         params.fechaCreacion.end = new Date(formValues.fechaHasta)
287:           .toISOString()
288:           .split('T')[0];
289:       }
290:     }
291:     return params;
292:   }
