20: @Component({
21:     selector: 'app-registro-contrato',
22:     templateUrl: './registro-contrato.component.html',
23:     styleUrls: ['./registro-contrato.component.css'],
24:     providers: [
25:         {
26:             provide: STEPPER_GLOBAL_OPTIONS,
27:             useValue: { showError: true },
28:         },
29:     ],
30:     standalone: false
31: })
32: export class RegistroContratoComponent implements OnInit, AfterViewInit {
33:   @ViewChildren(MatStep) steps!: QueryList<MatStep>;
34:   @ViewChild('stepper') stepper!: MatStepper;
35:   @ViewChild(PasoContratistasComponent)
36:   pasoContratistas!: PasoContratistasComponent;
37:   @ViewChild(PasoInfoGeneralComponent)
38:   pasoInfoGeneral!: PasoInfoGeneralComponent;
39:   @ViewChild(PasoObligacionesComponent)
40:   pasoObligaciones!: PasoObligacionesComponent;
41:   @ViewChild(PasoInfoPresupuestalComponent)
42:   pasoInfoPresupuestal!: PasoInfoPresupuestalComponent;
43: 
44:   orientation: 'horizontal' | 'vertical' = 'horizontal';
45: 
46:   isLinear = false;
47:   showEspecificacionesTecnicas = false;
48:   showAplicaPoliza = false;
49:   stepsCompleted: BehaviorSubject<boolean[]> = new BehaviorSubject<boolean[]>(
50:     new Array(9).fill(false)
51:   );
52: 
53:   constructor(private breakpointObserver: BreakpointObserver) {}
54: 
55:   ngOnInit() {
56:     this.manejarResponsiveStepper();
57:   }
58: 
59:   onTipoCompromisoChange(tipoCompromisoId: string) {
60:     this.showEspecificacionesTecnicas =
61:       tipoCompromisoId === environment.ORDEN_ID.toString();
62: 
63:     if (!this.showEspecificacionesTecnicas) {
64:       const currentSteps = this.stepsCompleted.value;
65:       currentSteps[6] = true;
66:       this.stepsCompleted.next(currentSteps);
67:     }
68:   }
69: 
70:   onAplicaPolizaChange(aplicaPoliza: string) {
71:     this.showAplicaPoliza = aplicaPoliza == '1'; // 1 = Si, 0 = No
72:     if (!this.showAplicaPoliza) {
73:       const currentSteps = this.stepsCompleted.value;
74:       currentSteps[7] = true;
75:       this.stepsCompleted.next(currentSteps);
76:     }
77:   }
78: 
79:   goToNextStep() {
80:     if (this.stepper.selected) {
81:       this.stepper.selected.completed = true;
82:       this.stepper.next();
83:     }
84:   }
85: 
86:   ngAfterViewInit() {
87:     this.stepper.selectionChange.subscribe((event) => {
88:       if (event.previouslySelectedIndex === 3 && event.selectedIndex !== 3) {
89:         this.pasoContratistas.onStepLeave();
90:       }
91:     });
92:     this.steps.toArray().forEach((step, index) => {
93:       step.label = `Paso ${index + 1}`;
94:     });
95:   }
96: 
97:   stepCompleted(stepIndex: number, isCompleted: boolean) {
98:     const currentSteps = this.stepsCompleted.value;
99:     currentSteps[stepIndex] = isCompleted;
100:     this.stepsCompleted.next(currentSteps);
101:   }
102: 
103:   canProceedToStep(stepIndex: number): Observable<boolean> {
104:     return this.stepsCompleted.pipe(
105:       map((steps) => steps.slice(0, stepIndex).every((step) => step))
106:     );
107:   }
108: 
109:   manejarResponsiveStepper() {
110:     this.breakpointObserver
111:       .observe(['(max-width: 992px)'])
112:       .subscribe((result) => {
113:         this.orientation = result.matches ? 'vertical' : 'horizontal';
114:       });
115:   }
116: }

