247:   aprobarContrato() {
248:     let estados: number[] =
249:       flujoEstados[this.unidad_ejecutora_id]?.[this.estadoInternoActual];
250:     const rol = this.getRolPorEstado();
251: 
252:     if (!rol || !estados?.length) return;
253: 
254:     const [estadoActual, estadoAnterior] = estados;
255: 
256:     let estado_parametro_id = environment.ESTADOS_GENERALES.SUSCRITO;
257:     if (estadoActual === environment.ESTADOS_INTERNOS.APROBADO_JEFE) {
258:       estado_parametro_id = environment.ESTADOS_GENERALES.POR_SUSCRIBIR;
259:     }
260: 
261:     let estadoContrato: EstadoContrato = {
262:       contrato_general_id: this.contrato_general_id,
263:       usuario_id: this.usuario_id,
264:       usuario_rol: rol,
265:       estado_parametro_id,
266:       estado_interno_parametro_id: estadoActual,
267:     };
268: 
269:     if (this.numero_contrato == null) {
270:       this.generarNumeroContrato(estadoContrato, estadoAnterior);
271:     } else {
272:       this.crearEstadoAutomaticoContrato(estadoContrato, estadoAnterior);
273:     }
