276:   crearEstadoAutomaticoContrato(
277:     estadoContrato: EstadoContrato,
278:     estado: number,
279:     numeroContrato?: string
280:   ) {
281:     this.contratoGeneralCrudService
282:       .postEstadoContrato(estadoContrato)
283:       .subscribe({
284:         next: (response: any) => {
285:           if (response.id) {
286:             estadoContrato.estado_parametro_id =
287:               environment.ESTADOS_GENERALES.SUSCRITO;
288:             estadoContrato.estado_interno_parametro_id = estado;
289:             this.crearEstadoContrato(estadoContrato, numeroContrato);
290:           }
291:         },
292:         error: (error) =>
293:           this.handleError('Error al crear estado automático', error),
294:       });
295:   }
296: 
297:   crearEstadoContrato(estadoContrato: EstadoContrato, numeroContrato?: string) {
298:     this.contratoGeneralCrudService
299:       .postEstadoContrato(estadoContrato)
300:       .subscribe({
301:         next: (response: any) => {
302:           if (response.id) {
303:             this.alertService.showSuccessAlert(
304:               this.textos.enviado,
305:               'CONTRATO ENVIADO'
306:             );
307:             if (
308:               estadoContrato.estado_parametro_id ===
309:                 environment.ESTADOS_GENERALES.SUSCRITO &&
310:               !this.numero_contrato &&
311:               numeroContrato
312:             ) {
313:               this.guardarNumeroContrato(numeroContrato);
314:             }
315:           }
316:         },
317:         error: (error) =>
318:           this.handleError('Error al crear estado de contrato', error),
319:       });
320:   }
321: 
322:   // Generar número de contrato si aplica
323:   generarNumeroContrato(estadoContrato: EstadoContrato, estado: number) {
324:     this.contratoGeneralMidService
325:       .postNumeroContrato({
326:         unidad_ejecutora_id: this.unidad_ejecutora_id,
327:         vigencia: this.vigencia,
328:         estado: environment.ESTADOS_GENERALES.SUSCRITO,
329:       })
330:       .subscribe({
331:         next: (response: ApiResponse<any>) => {
332:           if (response.Success && response.Status === 200) {
333:             this.crearEstadoAutomaticoContrato(
334:               estadoContrato,
335:               estado,
336:               response.Data
337:             );
338:           } else {
339:             this.alertService.showErrorAlert(
340:               'Error al generar número de contrato',
341:               'Por favor, intente de nuevo'
342:             );
343:           }
344:         },
345:         error: (error) => {
346:           this.handleError('Error al generar número de contrato', error);
347:         },
348:       });
349:   }
350: 
351:   // Actualizar el contrato para guardar el número de contrato
352:   guardarNumeroContrato(numeroContrato: string) {
353:     this.contratoGeneralCrudService
354:       .put(this.contrato_general_id, { numero_contrato: numeroContrato })
355:       .subscribe({
356:         next: (response: ApiResponse<any>) => {
357:           if (response.Success && response.Status === 200) {
358:             this.alertService.showSuccessAlert(
359:               `Número de contrato generado: ${numeroContrato}`
360:             );
361:           } else {
362:             this.alertService.showErrorAlert(
363:               'Error al guardar número de contrato',
364:               'Por favor, intente de nuevo'
365:             );
366:           }
367:         },
368:         error: (error) => {
369:           this.handleError('Error al guardar número de contrato', error);
370:         },
371:       });
372:   }
