6: 
7: /**
8:  * This class manage the http connections with internal REST services. Use the response format {
9:  *  Code: 'xxxxx',
10:  *  Body: 'Some Data' (this element is returned if the request is success)
11:  *  ...
12:  * }
13:  */
14: @Injectable({
15:   providedIn: 'root',
16: })
17: export class RequestManager {
18:   private path!: any;
19:   public httpOptions: any;
20:   constructor(private http: HttpClient, private errManager: HttpErrorManager) {
21:     const acces_token = window.localStorage.getItem('access_token');
22:     if (acces_token !== null) {
23:       this.httpOptions = {
24:          headers: new HttpHeaders({
25:            'Content-Type': 'application/json',
26:            'Authorization': `Bearer ${acces_token}`,
27:          }),
28:       }
29:     }
30:   }
31: 
32: 
33:   /**
34:    * Use for set the source path of the service (service's name must be present at src/environment/environment.ts)
35:    * @param service: string
36:    */
37:   public setPath(service: string) {
38:     this.path = environment[service as keyof typeof environment];
39:   }
40: 
41: 
42:   /**
43:    * Perform a GET http request
44:    * @param endpoint service's end-point
45:    * @param params (an Key, Value object with que query params for the request)
46:    * @returns Observable<any>
47:    */
48:   get<T>(endpoint: string) {
49:     return this.http.get<T>(`${this.path}${endpoint}`, this.httpOptions).pipe(
50:       map((response) => response as T),
51:       catchError((error) => {
52:         throw error as ErrorResponse;
53:       })
54:     );
55:   }
56: 
57:   /**
58:    * Perform a POST http request
59:    * @param endpoint service's end-point
60:    * @param element data to send as JSON
61:    * @returns Observable<any>
62:    */
63:   post(endpoint: any, element: any) {
64:     return this.http.post<any>(`${this.path}${endpoint}`, element, this.httpOptions).pipe(
65:       catchError((error) => this.errManager.handleError(error)),
66:     );
67:   }
68: 
69:   /**
70:    * Perform a POST http request
71:    * @param endpoint service's end-point
72:    * @param element data to send as JSON
73:    * @returns Observable<any>
74:    */
75:   post_file(endpoint: any, element: any) {
76:     return this.http.post<any>(`${this.path}${endpoint}`, element, {    headers: new HttpHeaders({
77:       'Content-Type': 'multipart/form-data',
78:   })}).pipe(
79:       catchError((error) => this.errManager.handleError(error)),
80:     );
81:   }
82: 
83:   /**
84:    * Perform a PUT http request
85:    * @param endpoint service's end-point
86:    * @param element data to send as JSON, With the id to UPDATE
87:    * @returns Observable<any>
88:    */
89:   put(endpoint: any, element: { Id: any; }) {
90:     const path = (element.Id) ? `${this.path}${endpoint}/${element.Id}` : `${this.path}${endpoint}`;
91:     return this.http.put<any>(path, element, this.httpOptions).pipe(
92:       catchError((error) => this.errManager.handleError(error)),
93:     );
94:   }
95: 
96:   /**
97:    * Perform a DELETE http request
98:    * @param endpoint service's end-point
99:    * @param id element's id for remove
100:    * @returns Observable<any>
101:    */
102:   delete(endpoint: any, id: any) {
103:     return this.http.delete<any>(`${this.path}${endpoint}/${id}`, this.httpOptions).pipe(
104:       catchError((error) => this.errManager.handleError(error)),
105:     );
106:   }
107: 
108:   /**
109:    * Perform a PATCH http request
110:    * @param endpoint service's end-point
111:    * @param element data to send as JSON, With the id to UPDATE
112:    * @returns Observable<any>
