27: // Recorrer el menú para verificar si la URL y los parámetros existen
28: function checkUrlExists(menuItems: any, targetUrl: string, params: any): boolean {
29:   return menuItems.some((item: any) => {
30:     // Verificar la URL y los parámetros
31:     if (item.Url === targetUrl && checkParams(item.Params, params)) {
32:       return true;
33:     }
34:     if (item.Opciones && item.Opciones.length > 0) {
35:       return checkUrlExists(item.Opciones, targetUrl, params);
36:     }
37:     return false;
38:   });
39: }
