41: // Verificar los parámetros de la ruta
42: function checkParams(expectedParams: any, actualParams: any): boolean {
43:   if (!expectedParams) {
44:     return true; // No se requieren parámetros específicos
45:   }
46:   for (let key in expectedParams) {
47:     if (expectedParams[key] !== actualParams[key]) {
48:       return false; // Un parámetro no coincide
49:     }
50:   }
51:   return true; // Todos los parámetros coinciden
52: }
